/*
 * Tokens de design em CSS puro. Todo estilo novo usa estas variáveis; o tema escuro
 * troca os valores sob `html.dark`. Não depende de Tailwind.
 */
:root {
  --cor-fundo: #f8fafc;
  --cor-superficie: #ffffff;
  --cor-superficie-alt: #f1f5f9;
  --cor-borda: #e2e8f0;
  --cor-borda-forte: #cbd5e1;
  --cor-texto: #0f172a;
  --cor-texto-suave: #475569;
  --cor-texto-mudo: #64748b;
  --cor-primaria: #047857;
  --cor-primaria-hover: #065f46;
  --cor-primaria-suave: #d1fae5;
  --cor-sobre-primaria: #ffffff;
  --cor-perigo: #b91c1c;
  --cor-perigo-hover: #991b1b;
  --cor-perigo-suave: #fee2e2;
  --cor-aviso: #b45309;
  --cor-aviso-suave: #fef3c7;
  --cor-sucesso: #047857;
  --cor-sucesso-suave: #d1fae5;
  --cor-info: #0369a1;
  --cor-info-suave: #e0f2fe;
  --cor-foco: #059669;

  --esp-1: 0.25rem;
  --esp-2: 0.5rem;
  --esp-3: 0.75rem;
  --esp-4: 1rem;
  --esp-5: 1.25rem;
  --esp-6: 1.5rem;
  --esp-8: 2rem;

  --raio: 0.5rem;
  --raio-pequeno: 0.375rem;
  --raio-total: 999px;
  --sombra: 0 1px 2px rgb(15 23 42 / 0.08);
  --fonte: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --texto-xs: 0.75rem;
  --texto-sm: 0.875rem;
  --texto-base: 1rem;
  --texto-lg: 1.125rem;
  --texto-xl: 1.25rem;
  --texto-2xl: 1.5rem;
}

html.dark {
  color-scheme: dark;
  --cor-fundo: #0a1020;
  --cor-superficie: #111b2e;
  --cor-superficie-alt: #1e293b;
  --cor-borda: #334155;
  --cor-borda-forte: #475569;
  --cor-texto: #f8fafc;
  --cor-texto-suave: #cbd5e1;
  --cor-texto-mudo: #94a3b8;
  --cor-primaria: #34d399;
  --cor-primaria-hover: #6ee7b7;
  --cor-primaria-suave: #064e3b;
  --cor-sobre-primaria: #052e22;
  --cor-perigo: #f87171;
  --cor-perigo-hover: #fca5a5;
  --cor-perigo-suave: #450a0a;
  --cor-aviso: #fcd34d;
  --cor-aviso-suave: #451a03;
  --cor-sucesso: #6ee7b7;
  --cor-sucesso-suave: #052e22;
  --cor-info: #7dd3fc;
  --cor-info-suave: #0c4a6e;
  --cor-foco: #34d399;
}
import { PREFIXO } from '../storage/storage';

export const CHAVE_PREFERENCIAS = `${PREFIXO}preferencias`;

export type Tema = 'claro' | 'escuro' | 'sistema';
export const TEMAS: readonly Tema[] = ['claro', 'escuro', 'sistema'];

export interface Preferencias {
  tema: Tema;
  ocultarValores: boolean;
}

export const PREFERENCIAS_PADRAO: Preferencias = { tema: 'sistema', ocultarValores: false };

const CONSULTA_ESCURO = '(prefers-color-scheme: dark)';

/** Lê as preferências; JSON inválido ou campos com tipo errado caem nos padrões, campo a campo. */
export function lerPreferencias(storage: Storage): Preferencias {
  let bruto: unknown;
  try {
    const texto = storage.getItem(CHAVE_PREFERENCIAS);
    bruto = texto === null ? null : JSON.parse(texto);
  } catch {
    return { ...PREFERENCIAS_PADRAO };
  }
  const dados = typeof bruto === 'object' && bruto !== null ? (bruto as Record<string, unknown>) : {};
  return {
    tema: TEMAS.includes(dados.tema as Tema) ? (dados.tema as Tema) : PREFERENCIAS_PADRAO.tema,
    ocultarValores: typeof dados.ocultarValores === 'boolean' ? dados.ocultarValores : PREFERENCIAS_PADRAO.ocultarValores,
  };
}

/** Grava as preferências; lança se o armazenamento recusar. */
export function salvarPreferencias(prefs: Preferencias, storage: Storage): void {
  storage.setItem(CHAVE_PREFERENCIAS, JSON.stringify(prefs));
}

export function removerPreferencias(storage: Storage): void {
  try {
    storage.removeItem(CHAVE_PREFERENCIAS);
  } catch {
    /* sem armazenamento: nada a remover */
  }
}

export function consultaEscuro(): MediaQueryList | null {
  return typeof window !== 'undefined' && typeof window.matchMedia === 'function' ? window.matchMedia(CONSULTA_ESCURO) : null;
}

/** Aplica tema e privacidade às classes do <html>. */
export function aplicarPreferencias(prefs: Preferencias, raiz: HTMLElement = document.documentElement): void {
  const escuro = prefs.tema === 'escuro' || (prefs.tema === 'sistema' && consultaEscuro()?.matches === true);
  raiz.classList.toggle('dark', escuro);
  raiz.classList.toggle('ocultar-valores', prefs.ocultarValores);
}
export interface ItemNavegacao {
  to: string;
  rotulo: string;
}

/** Navegação principal, na ordem de exibição. */
export const itensNavegacao: ItemNavegacao[] = [
  { to: '/', rotulo: 'Dashboard' },
  { to: '/transacoes', rotulo: 'Transações' },
  { to: '/contas', rotulo: 'Contas' },
  { to: '/conciliacao', rotulo: 'Conciliação' },
  { to: '/cartoes', rotulo: 'Cartões' },
  { to: '/transferencias', rotulo: 'Transferências' },
  { to: '/assinaturas', rotulo: 'Assinaturas' },
  { to: '/calendario', rotulo: 'Calendário' },
  { to: '/fluxo', rotulo: 'Fluxo de caixa' },
  { to: '/orcamento', rotulo: 'Orçamento' },
  { to: '/orcamento-anual', rotulo: 'Orçamento anual' },
  { to: '/metas', rotulo: 'Metas' },
  { to: '/investimentos', rotulo: 'Investimentos' },
  { to: '/independencia', rotulo: 'Independência' },
  { to: '/dividas', rotulo: 'Dívidas' },
  { to: '/divisao', rotulo: 'Divisão' },
  { to: '/patrimonio', rotulo: 'Patrimônio' },
  { to: '/relatorios', rotulo: 'Relatórios' },
  { to: '/regras', rotulo: 'Regras' },
  { to: '/importar', rotulo: 'Importar CSV' },
  { to: '/importar-ofx', rotulo: 'Importar OFX' },
  { to: '/ajuda', rotulo: 'Ajuda' },
];
import { NavLink, Outlet } from 'react-router-dom';
import { OnboardingEAtalhos } from './OnboardingEAtalhos';
import { itensNavegacao } from '../navegacao';
import { PreferenciasProvider } from '../state/preferencias';
import { BotaoOcultarValores } from './BotaoOcultarValores';
import './Layout.css';

const classeLink = ({ isActive }: { isActive: boolean }) => `layout-link${isActive ? ' layout-link--ativo' : ''}`;

export function Layout() {
  return (
    <PreferenciasProvider>
    <div className="layout-raiz">
      <header className="layout-cabecalho">
        <div className="layout-cabecalho__interno">
          <span className="layout-marca">Finanças Pessoais</span>
          <nav aria-label="Principal" className="layout-nav">
            {itensNavegacao.map((item) => (
              <NavLink key={item.to} to={item.to} end={item.to === '/'} className={classeLink}>
                {item.rotulo}
              </NavLink>
            ))}
          </nav>
          <BotaoOcultarValores />
          <NavLink to="/configuracoes" className={classeLink}>
            Configurações
          </NavLink>
        </div>
      </header>
      <OnboardingEAtalhos />
      <main className="layout-principal">
        <Outlet />
      </main>
    </div>
    </PreferenciasProvider>
  );
}
.layout-raiz { min-height: 100vh; overflow-x: hidden; }
.layout-cabecalho { border-bottom: 1px solid var(--cor-borda); background: var(--cor-superficie); }
.layout-cabecalho__interno {
  box-sizing: border-box;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--esp-2) var(--esp-4);
  max-width: 72rem;
  margin: 0 auto;
  padding: var(--esp-3) var(--esp-4);
}
.layout-marca { font-size: var(--texto-lg); font-weight: 700; color: var(--cor-primaria); }
.layout-nav { display: flex; flex: 1 1 0; flex-wrap: wrap; gap: var(--esp-1); min-width: 0; }
.layout-link {
  white-space: nowrap;
  border-radius: var(--raio-pequeno);
  padding: var(--esp-2) var(--esp-3);
  font-size: var(--texto-sm);
  font-weight: 500;
  color: var(--cor-texto-suave);
  text-decoration: none;
}
.layout-link:hover { background: var(--cor-borda); }
.layout-link:focus { outline: none; }
.layout-link:focus-visible { outline: 2px solid var(--cor-foco); outline-offset: 1px; }
.layout-link--ativo, .layout-link--ativo:hover { background: var(--cor-primaria); color: var(--cor-sobre-primaria); }
.layout-principal {
  box-sizing: border-box;
  max-width: 72rem;
  margin: 0 auto;
  padding: var(--esp-6) var(--esp-4);
}
@media print {
  .layout-cabecalho { display: none; }
}
import { useId, type ButtonHTMLAttributes, type HTMLAttributes, type InputHTMLAttributes, type ReactNode, type SelectHTMLAttributes } from 'react';
import '../styles/layout.css';
import './ui.css';

const juntar = (...partes: (string | false | undefined)[]) => partes.filter(Boolean).join(' ');

type VarianteBotao = 'primario' | 'secundario' | 'perigo' | 'link';

export function Botao({
  variante = 'primario',
  className = '',
  type = 'button',
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement> & { variante?: VarianteBotao }) {
  return <button type={type} className={juntar('ui-botao', `ui-botao--${variante}`, className)} {...props} />;
}

interface CampoProps {
  label: string;
  erro?: string;
  dica?: string;
}

function Mensagem({ id, erro, dica }: { id: string; erro?: string; dica?: string }) {
  if (erro) {
    return (
      <p id={id} role="alert" className="ui-campo__erro">
        {erro}
      </p>
    );
  }
  return dica ? (
    <p id={id} className="ui-campo__dica">
      {dica}
    </p>
  ) : null;
}

export function CampoTexto({ label, erro, dica, className = '', ...props }: CampoProps & InputHTMLAttributes<HTMLInputElement>) {
  const id = useId();
  const idMsg = `${id}-msg`;
  return (
    <div className="ui-campo">
      <label htmlFor={id} className="ui-campo__rotulo">
        {label}
      </label>
      <input
        id={id}
        aria-invalid={erro ? true : undefined}
        aria-describedby={erro || dica ? idMsg : undefined}
        className={juntar('ui-campo__controle', erro ? 'ui-campo__controle--erro' : undefined, className)}
        {...props}
      />
      <Mensagem id={idMsg} erro={erro} dica={dica} />
    </div>
  );
}

export function CampoSelect({
  label,
  erro,
  dica,
  className = '',
  children,
  ...props
}: CampoProps & SelectHTMLAttributes<HTMLSelectElement> & { children: ReactNode }) {
  const id = useId();
  const idMsg = `${id}-msg`;
  return (
    <div className="ui-campo">
      <label htmlFor={id} className="ui-campo__rotulo">
        {label}
      </label>
      <select
        id={id}
        aria-invalid={erro ? true : undefined}
        aria-describedby={erro || dica ? idMsg : undefined}
        className={juntar('ui-campo__controle', erro ? 'ui-campo__controle--erro' : undefined, className)}
        {...props}
      >
        {children}
      </select>
      <Mensagem id={idMsg} erro={erro} dica={dica} />
    </div>
  );
}

export function Cartao({ titulo, children, acoes, className = '' }: { titulo?: string; children: ReactNode; acoes?: ReactNode; className?: string }) {
  return (
    <section className={juntar('ui-cartao', className)}>
      {titulo || acoes ? (
        <div className="ui-cartao__cabecalho">
          {titulo ? <h2 className="ui-cartao__titulo">{titulo}</h2> : <span />}
          {acoes}
        </div>
      ) : null}
      {children}
    </section>
  );
}

export function TituloPagina({ children, acoes }: { children: ReactNode; acoes?: ReactNode }) {
  return (
    <div className="ui-titulo-pagina">
      <h1 className="ui-titulo-pagina__texto">{children}</h1>
      {acoes}
    </div>
  );
}

export function EstadoVazio({ titulo, children, acao }: { titulo: string; children?: ReactNode; acao?: ReactNode }) {
  return (
    <div className="ui-vazio">
      <p className="ui-vazio__titulo">{titulo}</p>
      {children ? <p className="ui-vazio__texto">{children}</p> : null}
      {acao ? <div className="ui-vazio__acao">{acao}</div> : null}
    </div>
  );
}

export function Alerta({ tipo = 'erro', children }: { tipo?: 'erro' | 'aviso' | 'sucesso'; children: ReactNode }) {
  return (
    <div role={tipo === 'erro' ? 'alert' : 'status'} className={`ui-alerta ui-alerta--${tipo}`}>
      {children}
    </div>
  );
}

/** Valor monetário com sinal e cor: positivo em verde, negativo em vermelho (o sinal vai no texto). */
export function Valor({ centavos, texto, className = '', ...props }: { centavos: number; texto: string } & HTMLAttributes<HTMLSpanElement>) {
  const cor = centavos < 0 ? 'ui-valor--negativo' : centavos > 0 ? 'ui-valor--positivo' : 'ui-valor--zero';
  // `tabular-nums` é o gancho da regra `html.ocultar-valores` (desfoque) em index.css.
  return (
    <span className={juntar('ui-valor', 'tabular-nums', cor, className)} {...props}>
      {texto}
    </span>
  );
}
