/* Reset mínimo (substitui o preflight do Tailwind) e base em CSS puro, via tokens. */
*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body, h1, h2, h3, h4, p, ul, ol, dl, dd, figure, blockquote, fieldset { margin: 0; }
ul, ol { padding: 0; list-style: none; }
fieldset { padding: 0; border: 0; min-width: 0; }
table { border-collapse: collapse; }
img, svg { display: block; max-width: 100%; }
button, input, select, textarea { font: inherit; color: inherit; margin: 0; }
button { cursor: pointer; background: none; border: 0; padding: 0; }
a { color: inherit; }

body {
  background: var(--cor-fundo);
  color: var(--cor-texto);
  font-family: var(--fonte);
  font-size: var(--texto-base);
  line-height: 1.5;
}

.tabular-nums { font-variant-numeric: tabular-nums; }

/* Privacidade: desfoca valores monetários (o componente Valor e qualquer .tabular-nums). */
html.ocultar-valores .tabular-nums {
  filter: blur(6px);
  user-select: none;
}
