/*
 * Tokens de design em CSS puro. Tema escuro é o padrão (html sem classe); `html.dark`
 * repete os mesmos valores (compatibilidade) e `html.claro` troca para o tema claro.
 * Não depende de Tailwind.
 */
:root,
html.dark {
  color-scheme: dark;
  /* Superfícies: 5 níveis separados por luminosidade */
  --cor-fundo: #0b0f17;
  --cor-superficie: #121826;
  --cor-superficie-2: #182032;
  --cor-superficie-alt: #1e2840;
  --cor-superficie-3: #263250;
  --cor-borda: #263250;
  --cor-borda-forte: #3a4868;
  /* Texto: 3 níveis */
  --cor-texto: #f1f5f9;
  --cor-texto-suave: #c0cadb;
  --cor-texto-mudo: #93a0b8;
  /* Marca (ação e foco) */
  --cor-primaria: #5eead4;
  --cor-primaria-hover: #99f6e4;
  --cor-primaria-suave: #0f3a3a;
  --cor-sobre-primaria: #042f2e;
  --cor-foco: #5eead4;
  /* Semânticas fixas */
  --cor-receita: #4ade80;
  --cor-despesa: #fb923c;
  --cor-perigo: #f87171;
  --cor-perigo-hover: #fca5a5;
  --cor-perigo-suave: #4a1a1a;
  --cor-aviso: #fcd34d;
  --cor-aviso-suave: #45330a;
  --cor-sucesso: #4ade80;
  --cor-sucesso-suave: #0f3320;
  --cor-info: #7dd3fc;
  --cor-info-suave: #0c3a58;
}

html.claro {
  color-scheme: light;
  --cor-fundo: #f4f6fa;
  --cor-superficie: #ffffff;
  --cor-superficie-2: #f8fafc;
  --cor-superficie-alt: #eef1f6;
  --cor-superficie-3: #e2e8f0;
  --cor-borda: #e2e8f0;
  --cor-borda-forte: #cbd5e1;
  --cor-texto: #0f172a;
  --cor-texto-suave: #475569;
  --cor-texto-mudo: #5b6a80;
