}

const FOCAVEIS = 'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';

/** Painel lateral acessível: role=dialog, foco preso, Esc fecha, foco volta ao gatilho. */
export function Drawer({ aberto, titulo, onFechar, children }: { aberto: boolean; titulo: string; onFechar: () => void; children: ReactNode }) {
  const painel = useRef<HTMLDivElement>(null);
  const fechar = useRef(onFechar);
  fechar.current = onFechar;

  useEffect(() => {
    if (!aberto) return;
    const anterior = document.activeElement as HTMLElement | null;
    const el = painel.current;
    (el?.querySelector<HTMLElement>(FOCAVEIS) ?? el)?.focus();
    const tecla = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.stopPropagation();
        fechar.current();
        return;
      }
      if (e.key !== 'Tab' || !el) return;
      const itens = Array.from(el.querySelectorAll<HTMLElement>(FOCAVEIS));
      if (itens.length === 0) return;
      const primeiro = itens[0];
      const ultimo = itens[itens.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) {
        e.preventDefault();
        ultimo.focus();
      } else if (!e.shiftKey && document.activeElement === ultimo) {
        e.preventDefault();
        primeiro.focus();
      }
    };
    document.addEventListener('keydown', tecla);
    return () => {
      document.removeEventListener('keydown', tecla);
      anterior?.focus?.();
    };
  }, [aberto]);

  if (!aberto) return null;
  return (
    <div className="drawer-fundo" onMouseDown={(e) => e.target === e.currentTarget && onFechar()}>
      <div ref={painel} className="drawer" role="dialog" aria-modal="true" aria-label={titulo} tabIndex={-1}>
        <div className="drawer__topo">
          <h2 className="drawer__titulo">{titulo}</h2>
          <button type="button" className="drawer__fechar" aria-label="Fechar" onClick={onFechar}>
            ×
          </button>
        </div>
        <div className="drawer__corpo">{children}</div>
      </div>
    </div>
  );
}

const paraExibicao = (iso: string) => (/^\d{4}-\d{2}-\d{2}$/.test(iso) ? `${iso.slice(8)}/${iso.slice(5, 7)}/${iso.slice(0, 4)}` : '');

function mascara(texto: string): string {
  const d = texto.replace(/\D/g, '').slice(0, 8);
  if (d.length <= 2) return d;
  if (d.length <= 4) return `${d.slice(0, 2)}/${d.slice(2)}`;
  return `${d.slice(0, 2)}/${d.slice(2, 4)}/${d.slice(4)}`;
}

function paraISO(exibicao: string): string {
  const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(exibicao);
  if (!m) return '';
  const [, d, mes, a] = m;
  const dt = new Date(Number(a), Number(mes) - 1, Number(d));
  return dt.getFullYear() === Number(a) && dt.getMonth() === Number(mes) - 1 && dt.getDate() === Number(d) ? `${a}-${mes}-${d}` : '';
}

type DateFieldProps = { label: string; erro?: string; dica?: string; value: string; onChange: (iso: string) => void } & Omit<InputHTMLAttributes<HTMLInputElement>, 'value' | 'onChange' | 'type'>;

/** Campo de data dd/mm/aaaa independente do locale; value/onChange usam AAAA-MM-DD ('' quando incompleto). */
export function DateField({ label, erro, dica, value, onChange, className = '', ...props }: DateFieldProps) {
  const id = useId();
  const [texto, setTexto] = useState(paraExibicao(value));
  const [ultimo, setUltimo] = useState(value);
  if (value !== ultimo) {
    setUltimo(value);
    if (paraISO(texto) !== value) setTexto(paraExibicao(value));
  }
  const msg = erro ?? dica;
  return (
    <div className="ui-campo">
      <label htmlFor={id} className="ui-campo__rotulo">
        {label}
      </label>
      <input
        id={id}
        type="text"
        inputMode="numeric"
        placeholder="dd/mm/aaaa"
        maxLength={10}
        autoComplete="off"
        aria-invalid={erro ? true : undefined}
        aria-describedby={msg ? `${id}-msg` : undefined}
        className={`ui-campo__controle tabular-nums ${erro ? 'ui-campo__controle--erro' : ''} ${className}`}
        {...props}
        value={texto}
        onChange={(e) => {
          const t = mascara(e.target.value);
          setTexto(t);
          const iso = paraISO(t);
          setUltimo(iso);
          onChange(iso);
        }}
      />
      {msg ? (
        <p id={`${id}-msg`} role={erro ? 'alert' : undefined} className={erro ? 'ui-campo__erro' : 'ui-campo__dica'}>
          {msg}
        </p>
      ) : null}
    </div>
  );
}

