import { useMemo, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { LinhaOrcamentoItem } from '../components/LinhaOrcamentoItem';
import { Alerta, Botao, Cartao, CampoTexto, EstadoVazio, TituloPagina } from '../components/ui';
import { hojeISO, mesDe, mesValido, nomeMes, somarMeses } from '../domain/date';
import { formatarMoeda } from '../domain/money';
import { copiarMesAnterior, definirLimite, linhasOrcamento, mesTemLimites, removerLimite, totaisOrcamento } from '../domain/orcamento';
import { useEstado, useStore } from '../state/store';
import './OrcamentoPage.css';

export function OrcamentoPage() {
  const store = useStore();
  const estado = useEstado();
  const [params, setParams] = useSearchParams();
  const [erro, setErro] = useState<string | null>(null);

  const mesParam = params.get('mes') ?? '';
  const mes = mesValido(mesParam) ? mesParam : mesDe(hojeISO());
  const irPara = (novo: string) => setParams({ mes: novo }, { replace: true });

  const linhas = useMemo(() => linhasOrcamento(estado, mes), [estado, mes]);
  const totais = useMemo(() => totaisOrcamento(linhas), [linhas]);
  const semLimites = !mesTemLimites(estado, mes);
  const podeCopiar = semLimites && mesTemLimites(estado, somarMeses(mes, -1));
  const estouradas = linhas.filter((l) => l.estado === 'estourado').length;

  return (
    <div>
      <TituloPagina>Orçamento</TituloPagina>
      <div className="orcamento-pagina">
        <Cartao>
          <div className="orcamento-navegacao">
            <Botao variante="secundario" onClick={() => irPara(somarMeses(mes, -1))}>
              Mês anterior
            </Botao>
            <div className="orcamento-campo-mes">
              <CampoTexto label="Mês" type="month" value={mes} onChange={(e) => mesValido(e.target.value) && irPara(e.target.value)} />
            </div>
            <Botao variante="secundario" onClick={() => irPara(somarMeses(mes, 1))}>
              Próximo mês
            </Botao>
            <p className="orcamento-mes-nome" aria-live="polite">
              {nomeMes(mes)}
            </p>
          </div>
        </Cartao>

        {erro ? <Alerta>{erro}</Alerta> : null}

        {podeCopiar ? (
          <Alerta tipo="aviso">
            <span className="orcamento-aviso">
              Este mês ainda não tem limites. Quer copiar os do mês anterior?
              <Botao
                variante="secundario"
                onClick={() => {
                  const r = store.aplicar((s) => copiarMesAnterior(s, mes));
                  setErro(r.ok ? null : r.erro);
                }}
              >
                Copiar limites do mês anterior
              </Botao>
            </span>
          </Alerta>
        ) : null}

        {linhas.length === 0 ? (
          <EstadoVazio titulo="Nenhuma categoria de despesa">Crie categorias de despesa na tela Transações para definir limites.</EstadoVazio>
        ) : (
          <>
            <div className="orcamento-totais" role="group" aria-label="Totais do mês">
              <Cartao>
                <p className="orcamento-total-rotulo">Soma dos limites</p>
                <p className="orcamento-total-valor" data-testid="total-limites">{formatarMoeda(totais.limites)}</p>
              </Cartao>
              <Cartao>
                <p className="orcamento-total-rotulo">Gasto nas categorias com limite</p>
                <p className="orcamento-total-valor" data-testid="total-gasto-com-limite">{formatarMoeda(totais.gastoComLimite)}</p>
              </Cartao>
              <Cartao>
                <p className="orcamento-total-rotulo">Gasto sem orçamento</p>
                <p className="orcamento-total-valor" data-testid="total-gasto-sem-orcamento">{formatarMoeda(totais.gastoSemOrcamento)}</p>
              </Cartao>
            </div>
            {estouradas > 0 ? (
              <Alerta>
                {estouradas === 1 ? '1 categoria estourou' : `${estouradas} categorias estouraram`} o limite neste mês.
              </Alerta>
            ) : null}
            <Cartao titulo="Limites por categoria">
              <ul className="orcamento-lista">
                {linhas.map((l) => (
                  <LinhaOrcamentoItem
                    key={l.categoria.id}
                    linha={l}
                    onDefinir={(limite) => store.aplicar((s) => definirLimite(s, l.categoria.id, mes, limite))}
                    onRemover={() => store.aplicar((s) => removerLimite(s, l.categoria.id, mes))}
                  />
                ))}
              </ul>
            </Cartao>
          </>
        )}
      </div>
    </div>
  );
}
import { useState, type FormEvent } from 'react';
import type { EstadoOrcamento, LinhaOrcamento } from '../domain/orcamento';
import { formatarMoeda, parseValor, valorParaCampo } from '../domain/money';
import type { Resultado } from '../domain/types';
import { Botao, CampoTexto, Valor } from './ui';
import './LinhaOrcamentoItem.css';

const ROTULO_ESTADO: Record<EstadoOrcamento, string> = {
  normal: 'Dentro do limite',
  atencao: 'Atenção: perto do limite',
  estourado: 'Estourado',
};

const ICONE_ESTADO: Record<EstadoOrcamento, string> = { normal: '✓', atencao: '!', estourado: '✕' };

const COR_BARRA: Record<EstadoOrcamento, string> = {
  normal: 'orcamento-barra--normal',
  atencao: 'orcamento-barra--atencao',
  estourado: 'orcamento-barra--estourado',
};

const COR_TEXTO: Record<EstadoOrcamento, string> = {
  normal: 'orcamento-estado--normal',
  atencao: 'orcamento-estado--atencao',
  estourado: 'orcamento-estado--estourado',
};

interface Props {
  linha: LinhaOrcamento;
  onDefinir: (limite: number) => Resultado<void>;
  onRemover: () => void;
}

export function LinhaOrcamentoItem({ linha, onDefinir, onRemover }: Props) {
  const { categoria, limite, gasto, restante, percentual, estado } = linha;
  const [editando, setEditando] = useState(false);
  const [texto, setTexto] = useState(limite === null ? '' : valorParaCampo(limite));
  const [erro, setErro] = useState<string | undefined>();

  const salvar = (e: FormEvent) => {
    e.preventDefault();
    const valor = parseValor(texto);
    if (valor === null) return setErro('Informe um valor válido, como 500,00.');
    if (valor < 0) return setErro('O limite não pode ser negativo.');
    const r = onDefinir(valor);
    if (!r.ok) return setErro(r.erro);
    setErro(undefined);
    setEditando(false);
  };

  return (
    <li className="orcamento-linha" data-testid={`orcamento-${categoria.id}`}>
      <div className="orcamento-cabecalho">
        <p className="orcamento-nome">
          {categoria.nome}
          {categoria.arquivada ? <span className="orcamento-selo">arquivada</span> : null}
        </p>
        <div className="orcamento-acoes">
          <Botao
            variante="secundario"
            aria-label={`${limite === null ? 'Definir limite de' : 'Editar limite de'} ${categoria.nome}`}
            onClick={() => {
              setTexto(limite === null ? '' : valorParaCampo(limite));
              setErro(undefined);
              setEditando(true);
            }}
          >
            {limite === null ? 'Definir limite' : 'Editar limite'}
          </Botao>
          {limite !== null ? (
            <Botao variante="secundario" aria-label={`Remover limite de ${categoria.nome}`} onClick={onRemover}>
              Remover limite
            </Botao>
          ) : null}
        </div>
      </div>

      {editando ? (
        <form onSubmit={salvar} noValidate aria-label={`Limite de ${categoria.nome}`} className="orcamento-form">
          <div className="orcamento-form-campo">
            <CampoTexto label={`Limite mensal de ${categoria.nome}`} value={texto} onChange={(e) => setTexto(e.target.value)} erro={erro} inputMode="decimal" placeholder="0,00" />
          </div>
          <div className="orcamento-form-acoes">
            <Botao type="submit">Salvar limite</Botao>
            <Botao variante="secundario" onClick={() => setEditando(false)}>
              Cancelar
            </Botao>
          </div>
        </form>
      ) : null}

      {limite === null ? (
        <p className="orcamento-sem-limite">
          Sem limite definido · Gasto: <span data-testid="gasto">{formatarMoeda(gasto)}</span>
        </p>
      ) : (
        <div className="orcamento-detalhe">
          <div
            role="progressbar"
            aria-label={`Consumo do orçamento de ${categoria.nome}`}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.min(percentual ?? (gasto > 0 ? 100 : 0), 100)}
            className="orcamento-trilho"
          >
            <div className={`orcamento-barra ${COR_BARRA[estado!]}`} style={{ width: `${Math.min(percentual ?? (gasto > 0 ? 100 : 0), 100)}%` }} />
          </div>
          <div className="orcamento-resumo">
            <span className={`orcamento-estado ${COR_TEXTO[estado!]}`} data-testid="estado">
              <span aria-hidden="true">{ICONE_ESTADO[estado!]} </span>
              {ROTULO_ESTADO[estado!]}
              {percentual !== null ? ` · ${percentual}%` : ''}
            </span>
            <span className="orcamento-texto">
              Gasto <span data-testid="gasto">{formatarMoeda(gasto)}</span> de <span data-testid="limite">{formatarMoeda(limite)}</span>
            </span>
            <span className="orcamento-texto">
              {restante! >= 0 ? 'Restante ' : 'Restante '}
              <Valor centavos={restante!} texto={formatarMoeda(restante!)} data-testid="restante" />
              {restante! < 0 ? (
                <>
                  {' '}
                  · Excedente <span data-testid="excedente">{formatarMoeda(-restante!)}</span>
                </>
              ) : null}
            </span>
          </div>
        </div>
      )}
    </li>
  );
}

